def scene18(s):
    s.layers[0]['fill']='#f8ecd4'
    s.circle('wine-planet',1171,443,339,'#7c2336')
    s.add('blue-orbit','M0,110C306,112 535,151 708,242C395,124 126,166 116,279C93,443 665,723 1672,734C1429,853 1133,884 853,842C495,790 135,626 0,501Z','#245f98',.97,'multiply')
    s.add('cyan-orbit','M0,318C579,277 1128,281 1672,334V566C1222,668 595,666 0,641V318ZM208,497C178,603 1160,586 1520,515C1742,470 1717,430 1462,403C985,355 262,389 208,497Z','#32a6b0',.90,'multiply')
    s.add('green-orbit','M501,0H898C598,434 561,701 908,941H443C290,555 392,200 501,0Z','#7e8943',.88,'multiply')
    s.add('red-orbit','M176,0H655C1049,147 1379,447 1672,790V941H1428C1225,518 723,147 176,0Z','#ff684d',.88,'multiply')
    # The reference's ink overlaps are not uniform multiply blending. Derive
    # intersection regions from the authored rings and sample each ink mixture.
    rings=s.layers[1:].copy()
    for layer in rings:
        layer['opacity']=1;layer['blend']=None
    for bits in range(1,32):
        if bits.bit_count()<2:continue
        mask=np.full((941,1672),255,np.uint8)
        for i,layer in enumerate(rings):
            mask=cv2.bitwise_and(mask,layer['mask'] if bits&(1<<i) else cv2.bitwise_not(layer['mask']))
        if np.count_nonzero(mask)<15:continue
        s.add(f'overprinted-ink-{bits}',rect(0,0,1672,941))
        s.layers[-1]['mask']=mask
        # Use the exact authored curves for clipping; raster masks only select
        # source colors and must never become the visible orbit boundaries.
        s.layers[-1]['exact_clips']=[
            layer['d'] if bits&(1<<i) else rect(0,0,1672,941)+layer['d']
            for i,layer in enumerate(rings)]

